def transform(grid):
    n = len(grid)
    base = [[grid[j][i] for j in range(n)] for i in range(n)]
    out = []
    for r in range(3 * n):
        br, lr = divmod(r, n)
        if br % 2:
            lr = n - 1 - lr
        row = []
        for c in range(3 * n):
            bc, lc = divmod(c, n)
            if bc % 2:
                lc = n - 1 - lc
            row.append(base[lr][lc])
        out.append(row)
    return out
